// Where the 2015–2020 audio sermon recordings live, and helpers for the
// archive page at /sermons/audio-archive. The recordings themselves are listed
// in audioSermons.ts (generated by scripts/build-audio-sermons.mjs).
//
// The MP3s are hosted on the Internet Archive (archive.org), not in this repo:
// together they are close to 1 GB, the GitHub Pages limit. If the item is ever
// renamed or moved, change the identifier here and every link follows.

import { audioSermons, type AudioSermon } from "./audioSermons";

export const audioArchivePath = "/sermons/audio-archive";

export const audioArchiveIdentifier = "ctc-audio-sermons-2015-2020";

/** The collection's own page on archive.org. */
export const audioArchiveItemUrl = `https://archive.org/details/${audioArchiveIdentifier}`;

/** In `npm run dev`, the MP3s play from the local download folder when it exists (see vite.config.js). */
const audioBaseUrl = __LOCAL_AUDIO_BASE__ ?? `https://archive.org/download/${audioArchiveIdentifier}/`;

export function audioSermonUrl(sermon: AudioSermon) {
  return `${audioBaseUrl}${encodeURIComponent(sermon.file)}`;
}

export const preservedSermons = audioSermons.filter((sermon) => sermon.preserved);

const years = audioSermons.map((sermon) => Number(sermon.date.slice(0, 4)));
export const audioArchiveFirstYear = Math.min(...years);
export const audioArchiveLastYear = Math.max(...years);

/** True when a theme is written in Tamil script, so it can be marked lang="ta". */
export function isTamil(text: string) {
  return /[஀-௿]/.test(text);
}

/** The two pastors get their own filter; everyone else is a guest speaker. */
export type SpeakerGroup = "godwin" | "jagan" | "guests";

export function speakerGroup(speaker: string): SpeakerGroup {
  if (speaker.includes("Godwin Kanakaraj")) return "godwin";
  if (speaker.includes("Jagan Sathiya Seelan")) return "jagan";
  return "guests";
}

/** 2028 → "34 min"; 4199 → "1 hr 10 min". */
export function formatDuration(seconds: number) {
  const minutes = Math.max(1, Math.round(seconds / 60));
  if (minutes < 60) return `${minutes} min`;
  return `${Math.floor(minutes / 60)} hr ${minutes % 60} min`;
}

/** Seconds → "m:ss" or "h:mm:ss" for the player clock. */
export function formatClock(seconds: number) {
  if (!Number.isFinite(seconds) || seconds < 0) return "0:00";
  const whole = Math.floor(seconds);
  const h = Math.floor(whole / 3600);
  const m = Math.floor((whole % 3600) / 60);
  const s = String(whole % 60).padStart(2, "0");
  return h ? `${h}:${String(m).padStart(2, "0")}:${s}` : `${m}:${s}`;
}

/** ISO 8601 duration for structured data: 2028 → "PT33M48S". */
export function isoDuration(seconds: number) {
  const m = Math.floor(seconds / 60);
  return `PT${m}M${seconds % 60}S`;
}
